(function(){
  'use strict';
  const SIGHTINGS='safariPocketbookSightings',PLACES='safariPocketbookSavedPlaces';
  const form=document.getElementById('sightingForm'),list=document.getElementById('sightingList'),empty=document.getElementById('journalEmpty');
  if(!form)return;
  let location=null;
  const read=key=>{try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch(error){return[]}};
  const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
  const escapeHtml=value=>String(value||'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const id=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)}
  function openJournal(){document.querySelectorAll('[data-view]').forEach(item=>item.classList.toggle('active',item.dataset.view==='journal'));document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.id==='journal'));window.scrollTo({top:0,behavior:'smooth'})}
  function setDefaultDate(){const now=new Date(Date.now()-new Date().getTimezoneOffset()*60000);document.getElementById('sightingDate').value=now.toISOString().slice(0,16)}
  function render(){const sightings=read(SIGHTINGS).sort((a,b)=>new Date(b.observedAt)-new Date(a.observedAt)),places=read(PLACES);document.getElementById('sightingCount').textContent=sightings.length;document.getElementById('savedPlaceCount').textContent=places.length;empty.hidden=!!sightings.length;list.innerHTML=sightings.map(item=>`<article><header><div><strong>${escapeHtml(item.animal)}</strong><small>${new Date(item.observedAt).toLocaleString()}</small></div><button data-delete-sighting="${item.id}" aria-label="Delete ${escapeHtml(item.animal)} sighting">×</button></header>${item.place?`<p class="entry-place">⌖ ${escapeHtml(item.place)}</p>`:''}${item.notes?`<p>${escapeHtml(item.notes)}</p>`:''}${item.location?`<small class="entry-coordinates">Coordinates: ${item.location.lat.toFixed(5)}, ${item.location.lng.toFixed(5)}</small>`:''}</article>`).join('');document.getElementById('savedPlaceList').innerHTML=places.length?places.map(place=>`<div><span><strong>${escapeHtml(place.name)}</strong><small>${escapeHtml(place.countryName)} · ${escapeHtml(place.type)}</small></span><button data-remove-place="${escapeHtml(place.name)}" aria-label="Remove ${escapeHtml(place.name)}">×</button></div>`).join(''):'<div class="no-saved-places">No places saved yet.</div>'}
  document.getElementById('animalOptions').innerHTML=(window.pocketWildlife||[]).map(animal=>`<option value="${escapeHtml(animal[0])}">${escapeHtml(animal[1])}</option>`).join('');document.getElementById('placeOptions').innerHTML=(window.safariPlaces||[]).map(place=>`<option value="${escapeHtml(place.name)}">${escapeHtml(place.countryName)}</option>`).join('');setDefaultDate();render();
  form.addEventListener('submit',event=>{event.preventDefault();const sightings=read(SIGHTINGS);sightings.push({id:id(),animal:document.getElementById('sightingAnimal').value.trim(),observedAt:document.getElementById('sightingDate').value,place:document.getElementById('sightingPlace').value.trim(),notes:document.getElementById('sightingNotes').value.trim(),location,createdAt:new Date().toISOString()});write(SIGHTINGS,sightings);form.reset();location=null;setDefaultDate();document.getElementById('locationPrivacy').textContent='Location is optional and is only saved inside this entry.';render();toast('Sighting saved to your field journal.')});
  document.getElementById('sightingLocation').addEventListener('click',()=>{const label=document.getElementById('locationPrivacy');if(!navigator.geolocation){label.textContent='Location is not available on this device.';return}label.textContent='Getting your location…';navigator.geolocation.getCurrentPosition(position=>{location={lat:position.coords.latitude,lng:position.coords.longitude,accuracy:Math.round(position.coords.accuracy)};label.textContent=`Location ready · accuracy about ${location.accuracy} m. Saved only with this entry.`},()=>label.textContent='Location permission was not granted. You can still save the sighting.',{enableHighAccuracy:true,timeout:12000,maximumAge:60000})});
  document.addEventListener('click',event=>{const del=event.target.closest('[data-delete-sighting]');if(del){write(SIGHTINGS,read(SIGHTINGS).filter(item=>item.id!==del.dataset.deleteSighting));render();toast('Sighting removed.');return}const remove=event.target.closest('[data-remove-place]');if(remove){write(PLACES,read(PLACES).filter(place=>place.name!==remove.dataset.removePlace));render();toast('Saved place removed.');return}const save=event.target.closest('[data-save-place]');if(save){const place=(window.safariPlaces||[]).find(item=>item.name===save.dataset.savePlace),saved=read(PLACES);if(place&&!saved.some(item=>item.name===place.name)){saved.push({name:place.name,countryName:place.countryName,type:place.type,savedAt:new Date().toISOString()});write(PLACES,saved);render();toast(`${place.name} saved to your journal.`)}else toast('That place is already saved.');return}const record=event.target.closest('[data-record-animal]');if(record){document.getElementById('sightingAnimal').value=record.dataset.recordAnimal;openJournal();document.getElementById('sightingPlace').focus()}});
  function addRecordButtons(){document.querySelectorAll('#animalGrid article:not(.gbif-card) .animal-actions').forEach(actions=>{if(actions.querySelector('.record-animal'))return;const name=actions.closest('article')?.querySelector('h2')?.textContent;if(!name)return;const button=document.createElement('button');button.type='button';button.className='record-animal';button.dataset.recordAnimal=name;button.textContent='＋ Sighting';actions.append(button)})}new MutationObserver(addRecordButtons).observe(document.getElementById('animalGrid'),{childList:true,subtree:true});addRecordButtons();
  document.addEventListener('click',event=>{const button=event.target.closest('[data-save-live-place]');if(!button)return;const place=(window.liveMapPlaces||[]).find(item=>item.id===button.dataset.saveLivePlace),saved=read(PLACES);if(place&&!saved.some(item=>item.name===place.name)){saved.push({...place,savedAt:new Date().toISOString()});write(PLACES,saved);render();toast(`${place.name} saved to your journal.`)}else toast('That place is already saved.')});
  document.getElementById('exportJournal').addEventListener('click',()=>{const backup={app:'African Safari Pocketbook',exportedAt:new Date().toISOString(),sightings:read(SIGHTINGS),savedPlaces:read(PLACES)},payload=JSON.stringify(backup,null,2),filename=`safari-pocketbook-journal-${new Date().toISOString().slice(0,10)}.json`;if(window.AndroidBridge){window.AndroidBridge.share(filename,payload);toast('Choose where to send or save your journal backup.');return}const blob=new Blob([payload],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Journal backup prepared.')});
})();
